mapper.select:
SELECT 'DR' AS recordType, A.MDFM_CLS_CD AS recordDetailType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemType, CASE WHEN A.MDFM_CLS_CD IN ('D009', 'D020', 'D035') THEN (SELECT Z.MDFM_NM FROM ODS.S_MRFMFORM Z WHERE Z.MDFM_ID = A.MDFM_ID AND Z.MDFM_FOM_SEQ = A.MDFM_FOM_SEQ) ELSE (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) END AS itemNm, CASE WHEN A.MDFM_CLS_CD IN ('D001', 'D002', 'D003', 'D004', 'D031') THEN TO_CHAR(A.MED_DT::DATETIME) ELSE TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD HH24:MI:SS') END AS writingDate, A.WRTR_DEPT_CD AS writingDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.WRTR_DEPT_CD) AS writingDeptNm, A.WRT_STF_NO AS writerStfNo, (SELECT Z.STF_NM FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO) AS writerNm, A.MDRC_ID || '_' || A.MDRC_FOM_SEQ || '_' || A.MDFM_ID || '_' || A.MDFM_FOM_SEQ AS keyId, A.PACT_ID AS pactId, A.PACT_TP_CD AS pactTpCd, DECODE(A.PACT_TP_CD, 'I', '입원', 'O', '외래', 'E', '응급', NULL) AS pactTpNm, A.PT_MED_DEPT_CD AS ptMedDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.PT_MED_DEPT_CD) AS ptMedDeptNm, ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS sortSeq, NULL AS note, A.MDFM_ID AS mdfmId, A.MDFM_FOM_SEQ AS mdfmFomSeq, A.MDRC_ID AS mdrcId, A.MDRC_FOM_SEQ AS mdrcFomSeq, NULL AS examKey, NULL AS pacsImgIptnCd, NULL AS accsId, NULL AS recType, NULL AS geneExmYn, CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END AS mdrcWrtStsCdYn, NULL AS opExptRegId FROM ODS.S_MRDDRECM A WHERE A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD NOT IN ('D005', 'D006', 'D007', 'D010', 'D011') AND A.MDFM_CLS_CD IN
#{item}
AND ( (A.MDFM_CLS_CD IN ('D001', 'D002', 'D003', 'D004', 'D031') AND A.MED_DT::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE) OR (A.MDFM_CLS_CD NOT IN ('D001', 'D002', 'D003', 'D004', 'D031') AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE) ) AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd}) AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo} AND NOT EXISTS(SELECT 1 FROM ODS.S_MRFMFORM Z WHERE A.MDFM_ID = Z.MDFM_ID AND A.MDFM_FOM_SEQ = Z.MDFM_FOM_SEQ AND Z.MDFM_CLS_CD = 'D020' AND Z.MDFM_APY_CTRA_CD = 4) AND NOT EXISTS(SELECT 1 FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO AND Z.OCTY_TP_CD = 'Z06') ORDER BY writingDate DESC, sortSeq

SELECT 'DR' AS recordType, A.MDFM_CLS_CD AS recordDetailType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemNm, TO_CHAR(NVL(B.OP_DTM, A.MDF_REC_DTM), 'YYYY-MM-DD HH24:MI:SS') AS writingDate, A.WRTR_DEPT_CD AS writingDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.WRTR_DEPT_CD) AS writingDeptNm, A.WRT_STF_NO AS writerStfNo, (SELECT Z.STF_NM FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO) AS writerNm, NULL AS keyId, A.PACT_ID AS pactId, A.PACT_TP_CD AS pactTpCd, DECODE(A.PACT_TP_CD, 'I', '입원', 'O', '외래', 'E', '응급', NULL) AS pactTpNm, A.PT_MED_DEPT_CD AS ptMedDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.PT_MED_DEPT_CD) AS ptMedDeptNm, ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS sortSeq, NULL AS note, A.MDFM_ID AS mdfmId, A.MDFM_FOM_SEQ AS mdfmFomSeq, A.MDRC_ID AS mdrcId, A.MDRC_FOM_SEQ AS mdrcFomSeq, NULL AS examKey, NULL AS pacsImgIptnCd, NULL AS accsId, NULL AS recType, NULL AS geneExmYn, CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END AS mdrcWrtStsCdYn, NULL AS opExptRegId FROM ODS.S_MRDDRECM A INNER JOIN ODS.S_MRDDRONE B ON A.MDRC_ID = B.MDRC_ID AND A.MDRC_FOM_SEQ = B.MDRC_FOM_SEQ WHERE A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD IN
#{item}
AND ((B.OP_DTM::DATE IS NOT NULL AND B.OP_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE) OR (B.OP_DTM::DATE IS NULL AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE)) AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd}) AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND B.OPRC_ELMT_CLS_CD = '17' AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo} AND NOT EXISTS(SELECT 1 FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO AND Z.OCTY_TP_CD = 'Z06') ORDER BY writingDate DESC, sortSeq

SELECT 'DR' AS recordType, A.MDFM_CLS_CD AS recordDetailType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemNm, TO_CHAR(NVL(B.DS_DT, A.MDF_REC_DTM), 'YYYY-MM-DD HH24:MI:SS') AS writingDate, A.WRTR_DEPT_CD AS writingDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.WRTR_DEPT_CD) AS writingDeptNm, A.WK_STF_NO AS writerStfNo, (SELECT Z.STF_NM FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO) AS writerNm, NULL AS keyId, A.PACT_ID AS pactId, A.PACT_TP_CD AS pactTpCd, DECODE(A.PACT_TP_CD, 'I', '입원', 'O', '외래', 'E', '응급', NULL) AS pactTpNm, A.PT_MED_DEPT_CD AS ptMedDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.PT_MED_DEPT_CD) AS ptMedDeptNm, ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS sortSeq, NULL AS note, A.MDFM_ID AS mdfmId, A.MDFM_FOM_SEQ AS mdfmFomSeq, A.MDRC_ID AS mdrcId, A.MDRC_FOM_SEQ AS mdrcFomSeq, NULL AS examKey, NULL AS pacsImgIptnCd, NULL AS accsId, NULL AS recType, NULL AS geneExmYn, CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END AS mdrcWrtStsCdYn, NULL AS opExptRegId FROM ODS.S_MRDDRECM A LEFT OUTER JOIN (SELECT Q.PT_NO AS PT_NO , Q.PACT_ID AS PACT_ID , Q.DS_DTM AS DS_DT FROM ODS.S_ACPPRAAM Q WHERE Q.PT_NO = #{ptNo} UNION ALL SELECT Q.PT_NO AS PT_NO , Q.PACT_ID AS PACT_ID , Q.CHOT_DTM AS DS_DT FROM ODS.S_ACPPRETM Q WHERE Q.PT_NO = #{ptNo} ) B ON A.PT_NO = B.PT_NO AND A.PACT_ID = B.PACT_ID WHERE A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD IN
#{item}
AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd}) AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo} AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND ((B.DS_DT::DATE IS NOT NULL AND B.DS_DT::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE AND A.PT_NO = B.PT_NO AND A.PACT_ID = B.PACT_ID) OR (B.DS_DT::DATE IS NULL AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE)) AND NOT EXISTS(SELECT 'Y' FROM ODS.S_CNLRRUSD W WHERE W.STF_NO = A.WRT_STF_NO AND W.OCTY_TP_CD IN ('Z06'))

SELECT 'DR' AS recordType, A.MDFM_CLS_CD AS recordDetailType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = A.MDFM_CLS_DTL_CD) AS itemNm, CASE WHEN A.MDFM_CLS_CD IN ('D001', 'D002', 'D003', 'D004', 'D031') THEN TO_CHAR(A.MED_DT::DATETIME) ELSE TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD HH24:MI:SS') END AS writingDate, A.WRTR_DEPT_CD AS writingDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.WRTR_DEPT_CD) AS writingDeptNm, A.WRT_STF_NO AS writerStfNo, (SELECT Z.STF_NM FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO) AS writerNm, NULL AS keyId, A.PACT_ID AS pactId, A.PACT_TP_CD AS pactTpCd, DECODE(A.PACT_TP_CD, 'I', '입원', 'O', '외래', 'E', '응급', NULL) AS pactTpNm, A.PT_MED_DEPT_CD AS ptMedDeptCd, (SELECT Z.DEPT_NM FROM ODS.S_PDEDBMSM Z WHERE Z.DEPT_CD = A.PT_MED_DEPT_CD) AS ptMedDeptNm, ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS sortSeq, NULL AS note, A.MDFM_ID AS mdfmId, A.MDFM_FOM_SEQ AS mdfmFomSeq, A.MDRC_ID AS mdrcId, A.MDRC_FOM_SEQ AS mdrcFomSeq, NULL AS examKey, NULL AS pacsImgIptnCd, NULL AS accsId, NULL AS recType, NULL AS geneExmYn, CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END AS mdrcWrtStsCdYn, NULL AS opExptRegId FROM ODS.S_MRDDRECM A WHERE A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD IN
#{item}
AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd}) AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo} AND NOT EXISTS(SELECT 1 FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO AND Z.OCTY_TP_CD = 'Z06') ORDER BY writingDate DESC, sortSeq

SELECT 'DR' AS recordType, B.MDFM_CLS_CD AS recordDetailType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = B.MDFM_CLS_DTL_CD) AS itemType, (SELECT Z.COMN_CD_NM FROM ODS.S_CCCCCSTE Z WHERE Z.COMN_GRP_CD = 'RDO062' AND Z.COMN_CD = B.MDFM_CLS_DTL_CD) AS itemNm, TO_CHAR(A.OP_EXPT_DT, 'YYYY-MM-DD HH24:MI:SS') AS writingDate, NULL AS writingDeptCd, NULL AS writingDeptNm, B.LSH_STF_NO AS writerStfNo, (SELECT Z.STF_NM FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = B.LSH_STF_NO) AS writerNm, NULL AS keyId, NULL AS pactId, NULL AS pactTpCd, NULL AS pactTpNm, NULL AS ptMedDeptCd, NULL AS ptMedDeptNm, ROW_NUMBER() OVER (PARTITION BY A.OP_EXPT_DT ORDER BY A.OP_EXPT_DT DESC) AS sortSeq, NULL AS note, 1 AS mdfmId, 1 AS mdfmFomSeq, NULL AS mdrcId, NULL AS mdrcFomSeq, NULL AS examKey, NULL AS pacsImgIptnCd, NULL AS accsId, NULL AS recType, NULL AS geneExmYn, 'Y' AS mdrcWrtStsCdYn, A.OP_EXPT_REG_ID AS opExptRegId FROM ODS.S_MRDDRARD A INNER JOIN ODS.S_MRDDRAFE B ON A.OP_EXPT_REG_ID = B.OP_EXPT_REG_ID AND B.AFCHG_ANRM_REC_VAL_ID IS NULL INNER JOIN ODS.S_MOOOPPAM C ON C.OP_EXPT_REG_ID = A.OP_EXPT_REG_ID WHERE A.PT_NO = #{ptNo} AND B.MDFM_CLS_CD IN
#{item}
AND A.LSH_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE AND B.LSH_DTM = (SELECT MAX(LSH_DTM) FROM ODS.S_MRDDRAFE D WHERE D.OP_EXPT_REG_ID = B.OP_EXPT_REG_ID AND D.MDFM_CLS_CD = B.MDFM_CLS_CD AND D.AFCHG_ANRM_REC_VAL_ID IS NULL) GROUP BY B.MDFM_CLS_CD, B.MDFM_CLS_DTL_CD, itemType, itemNm, A.OP_EXPT_DT, B.LSH_STF_NO, writerNm, A.OP_EXPT_REG_ID
